export type Mode = "Imports" | "Exports";

export type MonthlyValue = { month: string; value: number };

// Real monthly trade value (USD millions) aggregated from the uploaded Datamyne
// extracts. The extracts are snapshot months rather than a continuous series, so
// the months are sparse and lumpy; zero months are omitted. These figures are
// the summed declared values of the parsed shipment rows by month.
